llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "The closest high-transfer analogue, a benzamidine-containing peptidomimetic with multiple carboxylate and amide groups, had absolute bioavailability too low for oral use in humans; this directly supports low F for the query, which shares the benzamidine and zwitterionic polar topology.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Revefenacin, a large amide/basic-amine drug, had absolute oral bioavailability <3% in healthy volunteers and COPD patients; its high transfer score and shared amide/basic-amine features support low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Emixustat, a cyclohexyl-containing amino alcohol, showed low oral bioavailability in healthy subjects; the shared cyclohexyl and basic amine moieties support low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Avanafil had oral bioavailability of only 8–10% in humans, providing additional low-F evidence from a moderately polar heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Sulpiride had absolute F of 34±12.5%, above the 20% threshold, but it lacks the permanent amidinium/carboxylate zwitterion and is less polar; this contradictory evidence is only weakly transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "L-arginine, a zwitterionic guanidinium amino acid, reached ~68% oral F in humans, but its absorption is mediated by nutrient amino acid transporters not expected for the query; contradictory but low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Low. The query is a highly polar, fully ionized benzamidine-peptidomimetic with very low logD and high TPSA, predicting poor passive permeability. The highest-transfer direct analogue (benzamidine polyacid) had inadequate oral bioavailability, and several other low-F drugs reinforce this. High-F analogues are small nutrients, prodrugs, or actively transported folates and are not sufficiently transferable to overcome the low-F evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Record C22 appears internally inconsistent (vitamin D record vs folate-like SMILES) and was not weighted.",
    "High-F analogues such as arginine, folates, and perindoprilat may involve active transport or prodrug effects not applicable to the query.",
    "No permeability or transporter data for the query; active uptake could theoretically improve F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

